public static void solve(FastScanner sc, FastPrintStream pw) throws Exception {
    int t = sc.nextInt();
    for (int times = 0; times < t; times++) {
        long n = sc.nextLong();
        long m = sc.nextLong();
        long k = sc.nextLong();

        if (m == k) {
            pw.println(0);
            continue;
        }

        long divisor = (1L << m) - (1L << k);

        if (divisor == 0) {
            pw.println(0);
            continue;
        }

        long remainder = (1L << n) % divisor;
        pw.println(remainder % 10);
    }
}

